    const allSafeOn = safe.length > 0 && safe.every((r) => r.checked);
    const btn = $("arcAll");
    if (btn) btn.textContent = allSafeOn ? "☐ Deselect all" : `☑ Select all ${safe.length} safe`;
    const c = $("arcCount");
