      md.push(`It has **${p.userCount} direct user member${p.userCount === 1 ? "" : "s"}**, no nested groups, and **${p.nRef} Conditional Access assignment${p.nRef === 1 ? "" : "s"}**.`, "");
      md.push("### What happens", "");
